        for (uint32_t i = 0; i < NSTEP; i++) for (uint32_t j = 0; j < t->step[i].n && j < 4u; j++)
            t->step[i].note[j] = (uint8_t)scale_snap(t, clamp((int)t->step[i].note[j] + delta, 24, 108));
