        for (tries = 0, k = 0; k < ns && tries < 32u; tries++) {
            uint32_t p = gr() % 15u;
            if (on[p] && on[p + 1u] && !sl[p]) { sl[p] = 1; k++; if (pt[p + 1u] == 0u && gch(50)) pt[p + 1u] = 1; }
        }
