static int32_t gbass_near(int32_t lo, const gch_t *c, int32_t ref)   /* (a walk's root: the octave nearest the line) */
{
    int32_t n = gbass_root(lo, c);
    if (ref < 0) return n;
    if (n + 12 - ref < ref - n && n + 12 <= lo + 24) n += 12;
    if (ref - (n - 12) < n - ref && n - 12 >= lo - 3) n -= 12;
    return n;
}
