/* the voicing family of the genre's chords */
static uint32_t gvo_mode(void)
{
    uint32_t f = HXF(gs.hx);
    return gs.vm == VM_PLANE ? VO_PLANE : f == HF_COLOR || f == HF_CINE ? VO_OPEN : VO_CLOSE;
