        if (!s->acc && gch(12)) ST_MICRO_SET(s, grr(-4, 4) * 4);   /* (sixteenths: 0.9.1's MICRO is in 64ths) */
        if (!(s->hit & 1u) && gch(8)) step_set_chance(s, (uint32_t)grr(40, 85));
