                                                         * approach resolves into) */
        int32_t last = -1;
        for (i = 0; i < len; i++) {
            step_t *s = &t->step[i];
            int keep;
            if (s->time != ST_NOTE) continue;
            keep = last >= 0 && !gin_mode(last);
            last = s->note[0];
            if (!keep && i % 4u && !(s->flags & SF_ACCENT) && gin_mode(s->note[0]) && gr() % 100u < (60u - gs.amt[GP_BASS])) {
