                if (i + 1u < len && t->step[i + 1u].time == ST_TIE) gclear(&t->step[i + 1u]);
            }
        }
    }
    for (i = 0; i < len; i++) {                         /* (an approach left with nothing to go to: its chord's root) */
        step_t *s = &t->step[i];
