            c = (p > pv ? p - pv : pv - p) + (nv > p ? nv - p : p - nv) + (k ? 2 : 0) + (gl_pal(d) ? 0 : 4) +
                (d == L->n[i - 1u].d ? 5 : 0) + (gl_ct(d, x->at) ? 0 : x->at % 4u ? 1 : 3);   /* (beats 2 and 4: a
                                                         * passing note only where it makes the line move by steps) */
            if (c < bc) { bc = c; best = d; }
        }
