cd <repo>/firmware/firmware/src && python3 - <<'PY'
import re
s=open('amaru_gen.c').read()
start=s.index('static const genre_def_t GENRES')
end=s.index('\n};',start)
body=s[start:end]
rows=[]; i=0
# find top-level braces inside array
while True:
    j=body.find('{',i+1)
    if j<0: break
    depth=1; k=j+1
    while depth and k<len(body):
        if body[k]=='{': depth+=1
        elif body[k]=='}': depth-=1
        k+=1
    seg=body[j:k]
    if '"' in seg and re.search(r'BASS_\w+',seg):
        name=re.search(r'"([^"]+)"',seg).group(1)
        strs=re.findall(r'"([xXaA.]{16})"',seg)
        modes=re.findall(r'\b(BASS_\w+|PAD_\w+|LEAD_\w+)\b',seg)
        vals=re.search(r'\{ "'+re.escape(name)+r'", ([^,]+), ([^,]+), ([^,]+), (\w+), ([^,]+), ([^,]+),',seg)
        rows.append((name,strs,modes,vals.groups()))
    i=k
for r in rows:
    print(r[0], r[3], r[2])
print('\nshared kick/snare:')
for a in range(len(rows)):
  for b in range(a+1,len(rows)):
    ra,rb=rows[a],rows[b]
    if ra[1][:2]==rb[1][:2]: print(ra[0],rb[0])
print('\nbass mode collisions:')
from collections import defaultdict
d=defaultdict(list)
for r in rows: d[r[2][0]].append(r[0])
for k,v in d.items():
  if len(v)>1: print(k,v)
print('\nscale/root collisions:')
d=defaultdict(list)
for r in rows: d[(r[3][2],r[3][3])].append(r[0])
for k,v in d.items():
  if len(v)>1: print(k,v)
PY

