static uint32_t rng_state;
static uint32_t rnd(void)
{
    uint32_t x = rng_state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    if (!x)
        x = 0x9E3779B9u;
    rng_state = x;
    return x;
}
static int chance(uint32_t pct) { return pct && rnd() % 100u < pct; }
static int rr(int lo, int hi) { return hi <= lo ? lo : lo + (int)(rnd() % (uint32_t)(hi - lo + 1)); }

