static int scale_mode(uint8_t bunker_scale)
{
    switch (bunker_scale) {
    case SC_PHRY: return 1;
    case SC_DOR:  return 2;
    case SC_HARM: return 3;
    case SC_MAJ:  return 4;
    case SC_MPEN: return 5;
    default:      return 0;   /* natural minor */
