}
static int scale_deg(const amaru_plan_t *p, int deg)
{
    int m = scale_mode(p->scale);
    int n = SCALE_LEN[m];
    int oct = 0;
    while (deg < 0) { deg += n; oct--; }
    oct += deg / n;
    return oct * 12 + SCALE_STEPS[m][deg % n];
}
static int note_at(const amaru_plan_t *p, int deg, int octave)
{
