#define DV_KITOF(t) ((uint32_t)(t) >> 4)
#define DV_KTYPE(kit, lane) ((uint8_t)(((kit) << 4) | (lane)))

typedef struct {
    uint8_t type;                                        /* DVT_*, or a model kit's (DV_KTYPE) */
    uint8_t decay, tone, extra, level, accent;           /* 0..127 */
