    {998, 806, 1190, 300, 53, {64, 64, 40}, 2638},       /* CONGA  300 Hz (150..600), tau 30..300 ms */
    {1139, 947, 1331, 20, 32, {64, 64, 64}, 5215},       /* RIM    500 Hz (250..1000), tau 2..8 ms */
