 908	/* DIGITAL's eight algorithms as FM charts, read from src/eng_digital.c's switch (alg) (ui_test.c checks
 909	 * these tables against it). FM_CELL: per operator 1..4 its grid cell, the column in 24 px steps (bits 0..2)
 910	 * and the row above the output bus (bits 4..5; row 0 = the carriers). FM_MOD: per destination operator d a
 911	 * nibble at bit 4 d of the operators modulating it (bit k = operator k + 1). Operator 4 feeds itself (FB). */
 912	static const uint8_t FM_CELL[8][4] = {
 913	    {0x00, 0x10, 0x20, 0x30}, {0x01, 0x11, 0x20, 0x22}, {0x01, 0x10, 0x20, 0x12}, {0x01, 0x12, 0x10, 0x20},
 914	    {0x00, 0x10, 0x02, 0x12}, {0x00, 0x02, 0x04, 0x12}, {0x00, 0x02, 0x04, 0x14}, {0x00, 0x02, 0x04, 0x06}};
 915	static const uint16_t FM_MOD[8] = {0x0842, 0x00C2, 0x004A, 0x0806, 0x0802, 0x0888, 0x0800, 0x0000};
 916	/* Modulators above what they modulate, the carriers on the bottom row over the output bus (an arrow out).
 917	 * Carriers THEME with INK numerals, modulators RAISE with THEME ones; an operator at LEVEL 0: DIM numeral.
 918	 * Routes by IDX: DIM at 0, MID, THEME from 64; op 4's feedback loop MID (DIM at FB 0). The knob just turned
 919	 * (an operator's ratio or level, IDX, FB): ACCENT. Junction dots where routes split or merge. */
 920	static void graph_fm(const track_t *t, uint16_t c)
 921	{
 922	    uint32_t alg = (uint32_t)t->p[P_E0] & 7u, k, j, mods = FM_MOD[alg], car = 0, hop = 9;
 923	    uint32_t hot = ui.hot_t ? (uint32_t)cur_page()->id[ui.hot_col & 3u] : 0u;
 924	    int32_t x[4], y[4], lo = 7, hi = 0, top = 0, bus, cl = 240, cr = 0, idx = t->p[P_E4];
 925	    uint16_t ec = hot == P_E4 ? T_ACCENT : !idx ? T_DIM : idx < 64 ? T_MID : c;
 926	    if (hot >= P_E1 && hot <= P_E3) hop = hot - P_E1 + 1u;
 927	    else if (hot >= P_FM1_ATK && hot < P_E0) hop = (hot - P_FM1_ATK) / 5u;
 928	    for (k = 0; k < 4u; k++) {
 929	        int32_t col = FM_CELL[alg][k] & 7, row = FM_CELL[alg][k] >> 4;
 930	        lo = col < lo ? col : lo; hi = col > hi ? col : hi; top = row > top ? row : top;
1140	    if (ui.home)
1141	        return SK_SCOPE;
1142	    g = cur_page()->graph;
1143	    return g == GR_ADSR ? SK_ADSR : g == GR_LFO ? SK_LFO : g == GR_TRK ? SK_TRK : SK_TITLE;
1144	}
