 301	/* Discussion #127 (1.2): MENU > SCALE LEDS ON, the keys of the selected track's scale (ROOT, SCALE), bit k = key k, as
 302	 * the keys play now: the note a key gives with TRN (QNT SNAP / SEQ: the key's own note; the others round down onto
 303	 * the scale); QNT WHITE every white key (they walk the scale; the black ones are silent). *root: the keys of the
 304	 * scale's root. None where the engine maps the keys itself (DRUM's GM map, the slices): 0 there, and OFF */
 305	static uint32_t scale_leds(uint32_t *root)
 306	{
 307	    const track_t *t = TSEL;
 308	    const engine_t *e = ENGINES[eng_idx(t->eng_req)];
 309	    uint32_t k, m = 0, r = 0, mask = scale_mask(t), note;
 310	    int32_t pc;
 311	    *root = 0;
 312	    if (!(ui_rec_prefs & (PREF_SCALE_LEDS >> 8)))
 313	        return 0;
 314	    for (k = 0; k < 27u; k++) {
 315	        if (e->keys && e->keys(t, k) >= 0)
 316	            continue;
 317	        if (t->p[P_QUANT] == QN_WHITE) {
 318	            if ((note = kb_map(t, k)) > 127u)
 319	                continue;                               /* (a black key: silent) */
 320	            pc = (int32_t)note - t->p[P_TRANS];         /* (WHITE walks the scale before TRN) */
 321	        } else {
 322	            pc = 53 + (int32_t)k + t->p[P_TRANS];
 323	        }
 324	        pc = ((pc - t->p[P_ROOT]) % 12 + 12) % 12;
 325	        m |= ((mask >> pc) & 1u) << k;
 326	        r |= (uint32_t)(pc == 0) << k;
 327	    }
 328	    *root = r & m;
 329	    return m;
 330	}
