1377	/* a track whose sound's sample is missing (engines.c snd_missing: an empty user slot, a built-in set this build lacks;
1378	 * it plays a sine): the no-file icon and NO SAMPLE (ui.c MSG_NO_SAMPLE). Once per track and source: at power-on, a sound
1379	 * or project load, SRC / SET turned, a slot erased; again after another source or a project load. One a frame; after
1380	 * a message already showing (LOADED) as the second message. Not on notes: nothing in the audio path */
1381	static void sample_notice(void)
1382	{
1383	    uint32_t k, code;
1384	    for (k = 0; k < NTRK; k++) {
1385	        code = 0;
1386	        if (!snd_missing(&trk[k], &code)) {
1387	            snd_said[k] = 0;
