1401	/* 1.5.5 (#208): MIDI IN notes since the last frame (seq.c midi_seen): their tracks light (midi_lit), and with MENU > MIDI >
1402	 * AUTO SELECT ON a track that is not selected becomes the selected one, but not while the selected track has had notes
1403	 * within MF_HOLD_MS (two tracks played together, a chord across tracks: the selection stays) nor within MF_HOLD_MS of the
1404	 * last such switch (no flicker), nor with MIDI IN SEL (every note is the selected track's), the menu or a layer up, nor
1405	 * while the selected track is being edited (mf_busy). The lowest such track if several. 1: it switched */
1406	#define MF_HOLD_MS 250u
1407	/* every pass's start (the menu, NAME, SCREEN OFF too): the notes since the last pass light their tracks and are this
1408	 * pass's (mf_seen: SCREEN WAKE +MIDI, AUTO SELECT); a pass that returns before midi_follow drops them (no AUTO SELECT
1409	 * later from a note played in the menu, NAME or the dark) */
1410	static void midi_take(void)
1411	{
1412	    uint32_t k, now = fm1_ms | 1u;
1413	    fm1_irq_off();
1414	    mf_seen = midi_seen;
1415	    midi_seen = 0;
1416	    fm1_irq_on();
1417	    for (k = 0; k < NTRK; k++)
1418	        if ((mf_seen >> k) & 1u)
1419	            midi_lit_ms[k] = now;
1420	}
1421	/* an edit of the selected track in progress: a step held for a lock (STEP, the DRUM grid), a step being entered on the
1422	 * roll, a grid hit waiting for its key's release, a dialog */
1423	static int mf_busy(void)
1424	{
1425	    return lock_held() || (ui.entry_open && (fm1_in.notes & ~kb_layer)) || ui.plk_rm || ui.confirm;
1426	}
1427	static int midi_follow(void)
1428	{
1429	    static uint32_t sw_ms;                              /* the last switch, fm1_ms | 1 (0 none) */
1430	    uint32_t seen = mf_seen, k, now = fm1_ms | 1u, cand, lit;
1431	    mf_seen = 0;
1432	    if (!seen)
1433	        return 0;
1434	    lit = midi_lit_ms[song.sel];                        /* (the selected track's last note: midi_take lit it now if */
1435	                                                        /* this pass has one, and then nothing switches) */
1436	    cand = seen & ~(1u << song.sel);
1437	    k = 0;
1438	    if (cand && !((seen >> song.sel) & 1u) && (ui_rec_prefs & (PREF_MIDI_FOLLOW >> 8)) && song.g[G_ROUTE] != ROUTE_SEL &&
1439	        !ui.menu && !ui.layer && !mf_busy() && (!lit || now - lit >= MF_HOLD_MS) &&
1440	        (!sw_ms || now - sw_ms >= MF_HOLD_MS)) {
1441	        while (!((cand >> k) & 1u))
1442	            k++;
1443	        track_select(k);
1444	        sw_ms = now;
1445	        k = 1;
1446	    } else
1447	        k = 0;
1448	    return (int)k;
1449	}
