 559	 * private IMA state, 512 samples per frame; no audio voice state is touched.
 560	 * Cache follows the sample zone, selected note and user-slot generation. */
 561	#define SAMPLE_WAVE_COLS 96u
 562	static struct {
 563	    int16_t lo[SAMPLE_WAVE_COLS], hi[SAMPLE_WAVE_COLS];
 564	    const smp_zone_t *zone;
 565	    uint32_t key, gen, pos;
 566	    int32_t pred, index, peak;
 567	    uint8_t ready;
 568	} sample_wave;
 569	
 570	static uint32_t sample_wave_zone(const track_t *t)
 571	{
 572	    uint32_t si = (uint32_t)t->p[P_E0] % SMP_NALL, i, zi = 0xFFFFu;
 573	    if (si < SMP_NSETS) {
 574	        const smp_set_t *set = &SMP_SETS[si];
 575	        for (i = 0; i < set->nz; i++)
 576	            if (last_note >= SMP_ZONES[set->z0 + i].lo && last_note <= SMP_ZONES[set->z0 + i].hi) zi = set->z0 + i;
 577	        if (zi == 0xFFFFu && set->nz) zi = set->z0;
 578	    } else {
 579	        uint32_t k = si - SMP_NSETS;
 580	        for (i = 0; i < usr_nz[k]; i++)
 581	            if (last_note >= usr_zone[k][i].lo && last_note <= usr_zone[k][i].hi) zi = 0x8000u | k << 5 | i;
 582	        if (zi == 0xFFFFu && usr_nz[k]) zi = 0x8000u | k << 5;
 583	    }
 584	    return zi;
 585	}
 586	
 587	static void sample_wave_tick(const track_t *t)
 588	{
 589	    uint32_t zi = sample_wave_zone(t), key = zi + ((uint32_t)last_note << 16), i;
 590	    if (key != sample_wave.key || sample_wave.gen != smp_user_gen || !sample_wave.zone) {
 591	        sample_wave.key = key; sample_wave.gen = smp_user_gen;
 592	        sample_wave.zone = zi == 0xFFFFu ? 0 : smp_zone(zi);
 593	        sample_wave.pos = 0; sample_wave.pred = sample_wave.index = 0;
 594	        sample_wave.peak = 1; sample_wave.ready = 0;
 595	        for (i = 0; i < SAMPLE_WAVE_COLS; i++) sample_wave.lo[i] = sample_wave.hi[i] = 0;
 596	    }
 597	    const smp_zone_t *z = sample_wave.zone;
 598	    if (!z || !z->n || sample_wave.ready) return;
 599	    for (i = 0; i < 512u && sample_wave.pos < z->n; i++) {
 600	        uint32_t pos = sample_wave.pos, b = SMP_DATA[z->off + (pos >> 1)];
 601	        uint32_t code = (pos & 1u) ? b >> 4 : b & 15u;
 602	        int32_t step = IMA_STEP[sample_wave.index], d = step >> 3;
 603	        if (code & 4u) d += step;
 604	        if (code & 2u) d += step >> 1;
 605	        if (code & 1u) d += step >> 2;
 606	        sample_wave.pred = clamp(sample_wave.pred + ((code & 8u) ? -d : d), -32768, 32767);
 607	        sample_wave.index = clamp(sample_wave.index + IMA_IDX[code & 7u], 0, 88);
 608	        uint32_t col = pos * SAMPLE_WAVE_COLS / z->n;
 609	        int32_t v = sample_wave.pred, a = v < 0 ? -v : v;
 610	        if (v < sample_wave.lo[col]) sample_wave.lo[col] = (int16_t)v;
 611	        if (v > sample_wave.hi[col]) sample_wave.hi[col] = (int16_t)v;
 612	        if (a > sample_wave.peak) sample_wave.peak = a;
 613	        sample_wave.pos++;
 614	    }
 615	    sample_wave.ready = sample_wave.pos == z->n;
 616	}
