 623	    for (i = 0; i < SAMPLE_WAVE_COLS; i++) {
 624	        int32_t x = 12 + (int32_t)i * 216 / (SAMPLE_WAVE_COLS - 1u);
 625	        cv_line(x, 48 - sample_wave.hi[i] * 38 / sample_wave.peak,
 626	                x, 48 - sample_wave.lo[i] * 38 / sample_wave.peak, c);
