1443	    if (ei == ENGI_DRUM && e->npresets) {
1444	        t->p[P_ATK] = e->presets[0].env[0];
1445	        t->p[P_DEC] = e->presets[0].env[1];
1446	        t->p[P_SUS] = e->presets[0].env[2];
1447	        t->p[P_REL] = e->presets[0].env[3];
