1470	static void midi_pc_load(track_t *t, uint32_t n)
1471	{
1472	    uint32_t e = t->eng_req % NENGINES, k;
1473	    if (e == ENGI_DRUM) {
1474	        const param_desc_t *d = param_desc_of(e, P_E0);
1475	        for (k = (uint32_t)d->min; k <= (uint32_t)d->max && (enum_orig(d, (int32_t)k) != (int32_t)k || n--); k++)
1476	            ;
1477	        if (k <= (uint32_t)d->max)
1478	            t->p[P_E0] = (int16_t)k;
1479	        return;
1480	    }
1481	    if (n >= preset_shown(e)) {
1482	        int32_t s = (int32_t)(FM6_OWN + 1u + n - preset_shown(e));
1483	        if (e == ENGI_FM6 && fm6_bank_slot(s) >= 0 && fm6_slot_ok(s))
1484	            t->p[P_E7] = (int16_t)s;
1485	        return;
1486	    }
1487	    for (k = 0; preset_orig(ENGINES[e], k) != k || n--; k++)   /* the n-th shown preset */
1488	        ;
1489	    apply_preset_to(t, k);
1490	}
1491	static void midi_pc_poll(void)                       /* main loop (ui_input) */
1492	{
1493	    uint32_t k, v;
1494	    for (k = 0; k < NTRK; k++) {
1495	        if (!ui.mpc[k])
 545	            for (i = 0; i <= (uint32_t)(d->max - d->min) && i < 24u; i++)
 546	                ed_str(d->names[i], 8);
 547	        break;
 548	    case ED_STEP_GET:
 549	    case ED_STEP_SET: {
 550	        step_t *st;
 551	        if (na < 1u || a[0] >= NSTEP)
 552	            return;
 553	        st = &TSEL->step[a[0]];
 554	        if (cmd == ED_STEP_SET && na >= 9u && !chain_busy()) {
 555	            ed_step_put(st, a + 1, na - 1u);
 556	        }
 557	        ed_w.st[a[0]] = ed_step_sig(&seq_steps(TSEL)[a[0]]);
 558	        ed_b(a[0]);
 559	        ed_step_reply(&seq_steps(TSEL)[a[0]]);
 560	        break;
 561	    }
 562	    case ED_PRESET: {                                      /* engine, preset */
 563	        ed_load_t b;
 564	        if (na < 2u || a[0] >= NENGINES)
 565	            return;
 566	        ed_load_before(&b);
 567	#if !FELUCCA_FM4
 568	        if (a[0] == ENGI_DIGITAL)                          /* a DIGITAL preset (retired): its sound, as FM6 */
 569	            fm4_load_preset(TSEL, a[1]);
 570	        else
 571	#endif
 572	        {
 573	            if (a[0] != TSEL->eng_req)
 574	                set_engine(a[0]);
 575	            apply_preset(a[1]);
 576	        }
 577	        ed_load_after(&b);
 578	        ui.force = 1;
 579	        ed_b(ed_eng(TSEL));
 580	        ed_b(TSEL->preset);
 581	        break;
 582	    }
 583	    case ED_PROJECT:                                       /* 0 = load, 1 = save, 2 = query; slot 0..3 */
 584	        if (na < 2u || a[0] > 2u || a[1] >= 4u)
 585	            return;
 586	        if (a[0] == 1u) {
 587	            if (ed_flash_stop() || project_save(a[1]))
 588	                return;                              /* the legacy reply has no failure bit: do not confirm a failed save */
 589	        }
 590	        else if (a[0] == 0u)
1460	    if (midi_hint) {                                    /* MIDI notes into a track that is not selected */
1461	        uint32_t h = midi_hint;
1462	        midi_hint = 0;
1463	        if (!ui.msg_t && (h != midi_last || fm1_ms - midi_t > 4000u)) {
1464	            char b[4] = {'T', (char)('0' + h), 0, 0};
1465	            ui_say("MIDI IN -> ", b);
1466	            midi_last = h;
1467	            midi_t = fm1_ms;
1468	        }
1469	    }
1470	}
