 85	static int up_to_v4(up_rec_t *r)                 /* 1 = r is version 4 / 5 (now) */
 86	{
 87	    int16_t v[UP_PMAX];
 88	    uint32_t i;
 89	    if (r->ver >= 4u)
 90	        return 1;
