 94	        if ((v[i] = r->p[i]) < -64 || v[i] > 127)
 95	            return 0;
 96	    memset(r->packed, 0, sizeof r->packed);
 97	    r->ver = r->ver == 3u ? UP_VER_GRID : UP_VER;
 98	    for (i = 0; i < r->np; i++)
 99	        r->packed[i] = (uint8_t)(v[i] + 64);
