326	/* value string (<= 5 chars) and unit for a parameter value */
327	static void param_format(const param_desc_t *d, int32_t v, char *val, const char **unit)
328	{
329	    *unit = "";
330	    fmt_named = d->fmt == F_ENUM;
331	    switch (d->fmt) {
332	    case F_PCT:                                     /* a 0..100 range (SWG) is its value, others a share of 127 */
333	        fmt_int(val, d->max == 100 ? v : (v * 100 + 63) / 127);
334	        *unit = "%";
335	        break;
336	    case F_BIPCT:                                   /* -64..63 as -100..+100 % (1.5.5, #199: each side over its own
337	                                                     * range; up to 1.5.1 / 64 both ways, the top read +98) */
338	        fmt_int(val, v * 100 / 64);
339	        if (v > 0) {
340	            char t[8];
341	            fmt_int(t, v * 100 / 63);
342	            val[0] = '+';
343	            str_cpy(val + 1, t, 6);
344	        }
345	        *unit = "%";
346	        break;
347	    case F_TIME: {
348	        uint32_t ms10 = TIME_MS_X10[v & 127];
349	        if (ms10 < 100u) {
350	            fmt_fix(val, (int32_t)ms10, 1);
351	            *unit = "ms";
352	        } else if (ms10 < 10000u) {
353	            fmt_int(val, (int32_t)((ms10 + 5u) / 10u));
354	            *unit = "ms";
355	        } else {
356	            fmt_fix(val, (int32_t)(ms10 / 100u), 2);
357	            if (ms10 >= 100000u)
358	                fmt_fix(val, (int32_t)(ms10 / 1000u), 1);
359	            *unit = "s";
360	        }
361	        break;
362	    }
363	    case F_LFOHZ: {
364	        uint32_t h = LFO_HZ_X100[v & 127];
365	        if (h < 1000u)
366	            fmt_fix(val, (int32_t)h, 2);
367	        else
368	            fmt_fix(val, (int32_t)(h / 10u), 1);
369	        *unit = "Hz";
370	        break;
371	    }
372	    case F_CUTOFF: {
373	        uint32_t h = CUTOFF_HZ[v & 127];
374	        if (h < 1000u) {
375	            fmt_int(val, (int32_t)h);
376	            *unit = "Hz";
377	        } else {
378	            fmt_fix(val, (int32_t)(h / 100u), 1);
379	            *unit = "kHz";
380	        }
381	        break;
382	    }
383	    case F_DB:
384	        if (v <= 0) {
385	            str_cpy(val, "OFF", 6);
386	        } else {
387	            fmt_fix(val, LEVEL_DB_X10[v], 1);
388	            *unit = "dB";
389	        }
390	        break;
420	    default:
421	        if (d->names) {                               /* F_INT with a 0-terminated name list: the range */
422	            uint32_t k = 0;                           /* split evenly over the names (engine desc hooks) */
423	            while (d->names[k])
424	                k++;
425	            str_cpy(val, d->names[(uint32_t)(clamp(v, d->min, d->max) - d->min) * k / (uint32_t)(d->max - d->min + 1)], 6);
426	        } else {
427	            fmt_int(val, v);
428	        }
429	        if (d->unit)
430	            *unit = d->unit;
431	        break;
432	    }
433	}
