            continue;
        if (drum_from_phys(d->engine, &d->p[P_E0]) || drum_from_perc(d->engine, &d->p[P_E0]))
            target = ENGI_DRUM;
        else {
            target = eng_fallback(d->engine);
            for (i = 0; i < 8u; i++)
                d->p[P_E0 + i] = param_desc_of(target, P_E0 + i)->def;
        }
        d->engine = (uint8_t)target;
        d->preset = 0;
        hit |= 1u << k;
